        linear-gradient(180deg, #fbf8f4 0%, var(--color-bg) 100%);
      line-height: 1.5;
      min-height: 100vh;
    }

    img {
      display: block;
      max-width: 100%;
    }

    a {
      color: var(--color-link);
      text-decoration-thickness: 0.08em;
      text-underline-offset: 0.18em;
    }

    a:hover {
      text-decoration-thickness: 0.12em;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 1000;
      padding: 0.8rem 1rem;
      border-radius: 999px;
      background: var(--color-surface);
      box-shadow: var(--shadow);
      transform: translateY(-180%);
      transition: transform 0.2s ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .shell {
      width: min(100% - 2rem, var(--max-width));
      margin: 0 auto;
    }

    .site-header {
      padding: 1.1rem 0;
      position: sticky;
      top: 0;
      z-index: 40;
      backdrop-filter: blur(18px);
      background: color-mix(in srgb, var(--color-bg) 76%, transparent);
      border-bottom: 1px solid color-mix(in srgb, var(--color-border) 80%, transparent);
    }

    .site-header__bar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.8rem;
      text-decoration: none;
      color: var(--color-text);
      font-weight: 700;
      letter-spacing: 0.02em;
    }

    .brand-mark {
      inline-size: 2.8rem;
      block-size: 2.8rem;
      border-radius: 0.95rem;
      background:
        linear-gradient(145deg, var(--color-accent) 0%, #f2c29b 55%, #fff4e8 100%);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
    }

    .site-nav {
      display: flex;
      align-items: center;
      gap: 1.2rem;
      flex-wrap: wrap;
      justify-content: flex-end;
    }

    .site-nav a {
      color: var(--color-text);
      text-decoration: none;
      font-weight: 600;
    }

    .site-nav a:focus-visible,
    .site-header a:focus-visible,
    .btn:focus-visible,
    .icon-button:focus-visible,
    .tab-button:focus-visible {
      outline: 3px solid var(--color-focus);
      outline-offset: 3px;
    }

    .hero {
      padding: 3.2rem 0 2rem;
    }

    .hero-card {
      display: grid;
      grid-template-columns: 1.2fr 0.8fr;
      gap: 1.5rem;
      padding: 1.5rem;
      border: 1px solid var(--color-border);
      border-radius: calc(var(--radius-lg) + 8px);
      background: linear-gradient(135deg, rgba(255,255,255,0.92), rgba(255,247,239,0.82));
      box-shadow: var(--shadow);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.45rem 0.8rem;
      border-radius: 999px;
      background: var(--color-surface-alt);
      color: var(--color-muted-text);
      font-size: 0.92rem;
      font-weight: 600;
    }

    h1,
    h2,
    h3,
    p {
      margin: 0;
    }

    h1 {
      margin-top: 1rem;
      font-size: clamp(2.5rem, 5vw, 4.9rem);
      line-height: 0.96;
      letter-spacing: -0.05em;
      max-width: 11ch;
    }

    .lead {
      margin-top: 1rem;
      max-width: 58ch;
      color: var(--color-muted-text);
      font-size: 1.08rem;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.9rem;
      margin-top: 1.5rem;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      min-height: 3rem;
      padding: 0.8rem 1.2rem;
      border-radius: 999px;
      border: 1px solid transparent;
      font: inherit;
      font-weight: 700;
      text-decoration: none;
      cursor: pointer;
    }

    .btn--primary {
      background: var(--color-text);
      color: var(--color-surface);
    }

    .btn--ghost {
      background: var(--color-surface);
      color: var(--color-text);
      border-color: var(--color-border);
    }

    .hero-aside {
      display: grid;
      gap: 1rem;
      align-content: start;
    }

    .hero-spotlight,
    .stat-card,
    .content-card,
    .product-card,
    .deal-card {
      border-radius: var(--radius-md);
      border: 1px solid var(--color-border);
      background: var(--color-surface);
      box-shadow: 0 1px 0 rgba(255,255,255,0.7) inset;
    }

    .hero-spotlight {
      padding: 1.1rem;
      display: grid;
      gap: 1rem;
      min-height: 100%;
      background:
        linear-gradient(180deg, rgba(255,255,255,0.9), rgba(255,250,245,0.9)),
        radial-gradient(circle at top right, #ffe2ca 0, transparent 42%);
    }

    .spotlight-visual {
      aspect-ratio: 1 / 0.88;
      border-radius: 22px;
      border: 1px solid var(--color-border);
      background:
        linear-gradient(150deg, #d9774a 0%, #f7d7bf 34%, #fcf6ef 60%, #c9ddd8 100%);
      position: relative;
      overflow: hidden;
    }

    .spotlight-visual::before,
    .spotlight-visual::after {
      content: "";
      position: absolute;
      inset: auto;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.45);
    }

    .spotlight-visual::before {
      inline-size: 9rem;
      block-size: 9rem;
      top: 1rem;
      right: -1rem;
    }

    .spotlight-visual::after {
      inline-size: 13rem;
      block-size: 13rem;
      bottom: -4rem;
      left: -2rem;
    }

    .hero-spotlight__copy {
      display: grid;
      gap: 0.35rem;
    }

    .meta-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem 0.8rem;
      color: var(--color-muted-text);
      font-size: 0.92rem;
    }

    .meta-row span + span {
      position: relative;
    }

    .meta-row span + span::before {
      content: "•";
      margin-right: 0.8rem;
      color: var(--color-border);
    }

    .section {
      padding: 1.25rem 0 2rem;
    }

    .section-head {
      display: flex;
      justify-content: space-between;
      align-items: end;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-head p {
      max-width: 56ch;
      color: var(--color-muted-text);
    }

    .section h2 {
      font-size: clamp(1.5rem, 2vw, 2.2rem);
      letter-spacing: -0.03em;
    }

    .products-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card {
      display: grid;
      gap: 1rem;
      padding: 1rem;
    }

    .product-card__image {
      aspect-ratio: 0.95;
      border-radius: 20px;
      border: 1px solid var(--color-border);
      overflow: hidden;
      position: relative;
      background:
        linear-gradient(160deg, color-mix(in srgb, var(--swatch) 76%, white) 0%, color-mix(in srgb, var(--swatch) 30%, white) 55%, #fff 100%);
    }

    .product-card__image::before {
      content: "";
      position: absolute;
      inset: 18% 18% 15% 18%;
      border-radius: 24px;
      background:
        linear-gradient(180deg, rgba(255,255,255,0.62), rgba(255,255,255,0.1)),
        linear-gradient(135deg, color-mix(in srgb, var(--swatch) 92%, black) 0%, color-mix(in srgb, var(--swatch) 62%, white) 100%);
      transform: rotate(-4deg);
      box-shadow: 0 18px 26px rgba(23, 20, 18, 0.12);
    }

    .product-card__image::after {
      content: attr(data-badge);
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      background: rgba(255,255,255,0.85);
      color: var(--color-text);
      font-size: 0.8rem;
      font-weight: 700;
    }

    .product-card__body {
      display: grid;
      gap: 0.45rem;
    }

    .product-card__body p {
      color: var(--color-muted-text);
      font-size: 0.95rem;
    }

    .product-card__footer {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 0.8rem;
      margin-top: 0.2rem;
    }

    .price {
      font-size: 1.08rem;
      font-weight: 800;
    }

    .pill {
      display: inline-flex;
      align-items: center;
      gap: 0.35rem;
      padding: 0.35rem 0.6rem;
      border-radius: 999px;
      font-size: 0.82rem;
      font-weight: 700;
      background: var(--color-surface-alt);
      color: var(--color-muted-text);
    }

    .deals-layout {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 1rem;
    }

    .deal-card {
      padding: 1.25rem;
      display: grid;
      gap: 1rem;
    }

    .deal-card--accent {
      background:
        linear-gradient(180deg, rgba(255,255,255,0.9), rgba(255,245,238,0.95)),
        linear-gradient(135deg, #ffe2ca 0%, #fff 38%, #f2e5dc 100%);
    }

    .countdown {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 0.7rem;
    }

    .countdown div {
      padding: 0.9rem 0.7rem;
      border-radius: 18px;
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      text-align: center;
    }

    .countdown strong {
      display: block;
      font-size: 1.3rem;
    }

    .countdown span {
      color: var(--color-muted-text);
      font-size: 0.85rem;
    }

    .deal-list {
      display: grid;
      gap: 0.75rem;
    }

    .deal-list article {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: center;
      padding: 0.95rem 1rem;
      border-radius: 18px;
      background: var(--color-surface);
      border: 1px solid var(--color-border);
    }

    .deal-list p {
      color: var(--color-muted-text);
      font-size: 0.94rem;
    }

    .deal-list strong {
      display: block;
      margin-bottom: 0.15rem;
    }

    .content-grid {
      display: grid;
      grid-template-columns: 1fr 1fr 0.9fr;
      gap: 1rem;
    }

    .content-card {
      overflow: hidden;
    }

    .content-card__visual {
      min-height: 13rem;
      background:
        linear-gradient(140deg, color-mix(in srgb, var(--swatch) 74%, white) 0%, color-mix(in srgb, var(--swatch) 35%, white) 65%, #f9f2ec 100%);
      border-bottom: 1px solid var(--color-border);
      position: relative;
    }

    .content-card__visual::after {
      content: attr(data-label);
      position: absolute;
      left: 1rem;
      bottom: 1rem;
      padding: 0.4rem 0.65rem;
      border-radius: 999px;
      background: rgba(255,255,255,0.84);
      font-size: 0.8rem;
      font-weight: 700;
    }

    .content-card__body {
      padding: 1rem;
      display: grid;
      gap: 0.6rem;
    }

    .content-card__body p {
      color: var(--color-muted-text);
      font-size: 0.95rem;
    }

    .support-strip {
      margin: 0 0 2.5rem;
      padding: 1rem 0;
    }

    .support-strip__row {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .stat-card {
      padding: 1rem 1.1rem;
      background: var(--color-surface);
    }

    .stat-card strong {
      display: block;
      font-size: 1.3rem;
      margin-bottom: 0.15rem;
    }

    .stat-card p {
      color: var(--color-muted-text);
      font-size: 0.94rem;
    }

    .site-footer {
      padding: 2rem 0 3rem;
      color: var(--color-muted-text);
    }

    .site-footer__row {
      display: flex;
      justify-content: space-between;
      align-items: start;
      gap: 1rem;
      padding-top: 1rem;
      border-top: 1px solid var(--color-border);
    }

    .site-footer nav {
      display: flex;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    .live-note {
      min-height: 1.5rem;
      color: var(--color-muted-text);
      font-size: 0.92rem;
    }

    @media (max-width: 1024px) {
      .hero-card,
      .deals-layout,
      .content-grid {
        grid-template-columns: 1fr;
      }

      .products-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .support-strip__row {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 720px) {
      .site-header__bar,
      .section-head,
      .site-footer__row {
        flex-direction: column;
        align-items: start;
      }

      .hero {
        padding-top: 1.5rem;
      }

      .hero-card {
        padding: 1rem;
      }

      .products-grid,
      .countdown {
        grid-template-columns: 1fr;
      }

      .site-nav {
        justify-content: flex-start;
      }
    }

    @media (forced-colors: active) {
      * {
        forced-color-adjust: auto;
      }

      body {
        background: Canvas;
        color: CanvasText;
      }

      .site-header,
      .hero-card,
      .hero-spotlight,
      .product-card,
      .deal-card,
      .content-card,
      .stat-card,
      .btn--ghost {
        background: Canvas;
        border-color: ButtonBorder;
      }

      .btn--primary {
        background: ButtonFace;
        color: ButtonText;
        border-color: ButtonBorder;
      }

      .eyebrow,
      .pill,
      .product-card__image::after,
      .content-card__visual::after {
        background: Canvas;
        color: CanvasText;
        border: 1px solid ButtonBorder;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <header class="site-header">
