  <script>
    const promoNote = document.getElementById('promo-note');
    const addButtons = document.querySelectorAll('[data-product]');
    const countdown = {
      days: document.querySelector('[data-unit="days"]'),
      hours: document.querySelector('[data-unit="hours"]'),
      minutes: document.querySelector('[data-unit="minutes"]'),
      seconds: document.querySelector('[data-unit="seconds"]')
    };

    const dealEndsAt = new Date(Date.now() + 2 * 24 * 60 * 60 * 1000 + 14 * 60 * 60 * 1000 + 38 * 60 * 1000 + 12 * 1000);

    function pad(value) {
      return String(value).padStart(2, '0');
    }

    function renderCountdown() {
      const remaining = Math.max(0, dealEndsAt - new Date());
      const totalSeconds = Math.floor(remaining / 1000);
      const days = Math.floor(totalSeconds / 86400);
      const hours = Math.floor((totalSeconds % 86400) / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = totalSeconds % 60;

      countdown.days.textContent = pad(days);
      countdown.hours.textContent = pad(hours);
      countdown.minutes.textContent = pad(minutes);
      countdown.seconds.textContent = pad(seconds);
    }

    function announce(message) {
      promoNote.textContent = message;
      window.clearTimeout(announce.timer);
      announce.timer = window.setTimeout(() => {
        promoNote.textContent = '';
      }, 3200);
    }

    addButtons.forEach((button) => {
      button.addEventListener('click', () => {
        const product = button.getAttribute('data-product');
        announce(`${product} added to your shortlist.`);
      });
    });

    renderCountdown();
    window.setInterval(renderCountdown, 1000);
  </script>
