       --color-accent: #d9774a;
       --color-accent-strong: #a94f24;
       --color-success: #2d6a4f;
       --shadow: 0 16px 40px rgba(23, 20, 18, 0.08);
       --radius-lg: 28px;
       --radius-md: 20px;
       --radius-sm: 14px;
       --max-width: 1180px;
     }

     * {
       box-sizing: border-box;
     }

     html {
       scroll-behavior: smooth;
     }

     body {
       margin: 0;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--color-text);
       background:
         radial-gradient(circle at top left, #fff7ef 0, transparent 30%),
         linear-gradient(180deg, #fbf8f4 0%, var(--color-bg) 100%);
       line-height: 1.5;
       min-height: 100vh;
     }

     img {
       display: block;
       max-width: 100%;
     }

     a {
       color: var(--color-link);
       text-decoration-thickness: 0.08em;
       text-underline-offset: 0.18em;
     }

     a:hover {
       text-decoration-thickness: 0.12em;
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       z-index: 1000;
       padding: 0.8rem 1rem;
       border-radius: 999px;
       background: var(--color-surface);
       box-shadow: var(--shadow);
       transform: translateY(-180%);
       transition: transform 0.2s ease;
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     .shell {
       width: min(100% - 2rem, var(--max-width));
       margin: 0 auto;
     }

     .site-header {
       padding: 1.1rem 0;
       position: sticky;
       top: 0;
       z-index: 40;
       backdrop-filter: blur(18px);
       background: color-mix(in srgb, var(--color-bg) 76%, transparent);
       border-bottom: 1px solid color-mix(in srgb, var(--color-border) 80%, transparent);
     }

     .site-header__bar {
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 1rem;
     }

     .brand {
       display: inline-flex;
       align-items: center;
       gap: 0.8rem;
       text-decoration: none;
       color: var(--color-text);
       font-weight: 700;
       letter-spacing: 0.02em;
     }

     .brand-mark {
       inline-size: 2.8rem;
       block-size: 2.8rem;
       border-radius: 0.95rem;
       background:
         linear-gradient(145deg, var(--color-accent) 0%, #f2c29b 55%, #fff4e8 100%);
       box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
     }

     .site-nav {
       display: flex;
       align-items: center;
       gap: 1.2rem;
       flex-wrap: wrap;
       justify-content: flex-end;
     }

     .site-nav a {
       color: var(--color-text);
       text-decoration: none;
       font-weight: 600;
     }

     .site-nav a:focus-visible,
     .site-header a:focus-visible,
     .btn:focus-visible,
     .icon-button:focus-visible,
     .tab-button:focus-visible {
       outline: 3px solid var(--color-focus);
       outline-offset: 3px;
     }

     .hero {
       padding: 3.2rem 0 2rem;
     }

     .hero-card {
       display: grid;
       grid-template-columns: 1.2fr 0.8fr;
       gap: 1.5rem;
       padding: 1.5rem;
       border: 1px solid var(--color-border);
       border-radius: calc(var(--radius-lg) + 8px);
       background: linear-gradient(135deg, rgba(255,255,255,0.92), rgba(255,247,239,0.82));
       box-shadow: var(--shadow);
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 0.5rem;
       padding: 0.45rem 0.8rem;
       border-radius: 999px;
       background: var(--color-surface-alt);
       color: var(--color-muted-text);
       font-size: 0.92rem;
       font-weight: 600;
     }

     h1,
     h2,
     h3,
     p {
       margin: 0;
     }

     h1 {
       margin-top: 1rem;
       font-size: clamp(2.5rem, 5vw, 4.9rem);
       line-height: 0.96;
       letter-spacing: -0.05em;
       max-width: 11ch;
     }

     .lead {
       margin-top: 1rem;
       max-width: 58ch;
       color: var(--color-muted-text);
       font-size: 1.08rem;
     }

     .hero-actions {
       display: flex;
       flex-wrap: wrap;
       gap: 0.9rem;
       margin-top: 1.5rem;
     }

     .btn {
       display: inline-flex;
       align-items: center;
       justify-content: center;
       gap: 0.5rem;
       min-height: 3rem;
       padding: 0.8rem 1.2rem;
       border-radius: 999px;
       border: 1px solid transparent;
       font: inherit;
       font-weight: 700;
       text-decoration: none;
       cursor: pointer;
     }

     .btn--primary {
       background: var(--color-text);
       color: var(--color-surface);
     }

     .btn--ghost {
       background: var(--color-surface);
       color: var(--color-text);
       border-color: var(--color-border);
     }

     .hero-aside {
       display: grid;
       gap: 1rem;
       align-content: start;
     }

     .hero-spotlight,
     .stat-card,
     .content-card,
     .product-card,
     .deal-card {
       border-radius: var(--radius-md);
       border: 1px solid var(--color-border);
       background: var(--color-surface);
       box-shadow: 0 1px 0 rgba(255,255,255,0.7) inset;
     }

     .hero-spotlight {
       padding: 1.1rem;
       display: grid;
       gap: 1rem;
       min-height: 100%;
       background:
         linear-gradient(180deg, rgba(255,255,255,0.9), rgba(255,250,245,0.9)),
         radial-gradient(circle at top right, #ffe2ca 0, transparent 42%);
     }

     .spotlight-visual {
       aspect-ratio: 1 / 0.88;
       border-radius: 22px;
       border: 1px solid var(--color-border);
       background:
         linear-gradient(150deg, #d9774a 0%, #f7d7bf 34%, #fcf6ef 60%, #c9ddd8 100%);
       position: relative;
       overflow: hidden;
     }
')

